rng = np.random.default_rng(7)
z = np.linspace(0, 1, nz)
dz = z[1] - z[0]

def fwd_int(m):
    return np.cumsum(m) * dz

def adj_int(d):
    return np.cumsum(d) * dz            # as written by the user

def adj_int_fixed(d):
    return np.cumsum(d[::-1])[::-1] * dz  # true adjoint of the lower-triangular cumsum

K2 = 3e3 * np.exp(-((z[::4, None] - z[None]) ** 2) / 0.005)
Op2 = pylops.MatrixMult(K2)

mtrue = np.zeros(nz)
mtrue[30:45] = 1.0
mtrue[70:75] = -0.5
s1, s2 = 1e-4, 1.0
d1 = fwd_int(mtrue) + s1 * rng.standard_normal(nz)
d2 = Op2 @ mtrue + s2 * rng.standard_normal(K2.shape[0])

# Dot tests
x = rng.standard_normal(nz); y_ = rng.standard_normal(nz)
for name, adj in [("as written", adj_int), ("fixed", adj_int_fixed)]:
    Op1 = pylops.FunctionOperator(fwd_int, adj, nz, nz)
    print(f"dot test Op1 ({name}):", np.dot(Op1 @ x, y_), np.dot(x, Op1.H @ y_))

def run(label, adj, weight):
    Op1 = pylops.FunctionOperator(fwd_int, adj, nz, nz)
    if weight:
        Op1 = (1 / s1) * Op1
        Op2w = (1 / s2) * Op2
        yy = np.concatenate([d1 / s1, d2 / s2])
    else:
        Op2w = Op2
        yy = np.concatenate([d1, d2])
    Op = pylops.VStack([Op1, Op2w])
    minv = pylops.optimization.basic.lsqr(Op, yy, niter=300, damp=1e-3)[0]
    print(f"\n{label}")
    print("  d1 misfit:", np.linalg.norm(fwd_int(minv) - d1) / np.linalg.norm(d1))
    print("  d2 misfit:", np.linalg.norm(Op2 @ minv - d2) / np.linalg.norm(d2))
    print("  model error:", np.linalg.norm(minv - mtrue) / np.linalg.norm(mtrue))

run("A: as written (wrong adjoint, no weighting)", adj_int, False)
run("B: fixed adjoint, no weighting", adj_int_fixed, False)
run("C: fixed adjoint + noise weighting", adj_int_fixed, True)
